<?php
$page_title='ออเดอร์ร้านค้าของฉัน';require_once __DIR__.'/includes/auth_check.php';requireSeller();require_once __DIR__.'/config/database.php';$db=(new Database())->getConnection();$sellerId=(int)$_SESSION['user_id'];$message=$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);$orderId=(int)($_POST['order_id']??0);$status=(string)($_POST['status']??'');$carrier=trim((string)($_POST['carrier']??''));$tracking=trim((string)($_POST['tracking_number']??''));if(!in_array($status,['accepted','packing','shipped','delivered'],true)||($status==='shipped'&&($carrier===''||$tracking==='')))$error='กรุณากรอกสถานะและข้อมูลจัดส่งให้ครบ';else try{$owns=$db->prepare('SELECT 1 FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? AND p.seller_id=? LIMIT 1');$owns->execute([$orderId,$sellerId]);if(!$owns->fetchColumn())throw new RuntimeException('ไม่มีสิทธิ์จัดการออเดอร์นี้');$current=$db->prepare("SELECT COALESCE(status,'pending') FROM order_fulfillments WHERE order_id=? AND seller_id=?");$current->execute([$orderId,$sellerId]);$old=(string)($current->fetchColumn()?:'pending');$allowed=['pending'=>['accepted'],'accepted'=>['packing'],'packing'=>['shipped'],'shipped'=>['delivered'],'delivered'=>[]];if($old!==$status&&!in_array($status,$allowed[$old]??[],true))throw new RuntimeException('ไม่สามารถย้อนกลับหรือข้ามขั้นตอนการจัดส่งได้');$stmt=$db->prepare("INSERT INTO order_fulfillments(order_id,seller_id,status,carrier,tracking_number,shipped_at,delivered_at) VALUES(?,?,?,?,?,IF(?='shipped',NOW(),NULL),IF(?='delivered',NOW(),NULL)) ON DUPLICATE KEY UPDATE status=VALUES(status),carrier=VALUES(carrier),tracking_number=VALUES(tracking_number),shipped_at=COALESCE(shipped_at,VALUES(shipped_at)),delivered_at=COALESCE(delivered_at,VALUES(delivered_at))");$stmt->execute([$orderId,$sellerId,$status,$carrier?:null,$tracking?:null,$status,$status]);auditLog($db,'seller.fulfillment.update','order',$orderId,null,['from'=>$old,'status'=>$status,'carrier'=>$carrier,'tracking_number'=>$tracking]);$customer=$db->prepare('SELECT user_id,order_no FROM orders WHERE id=?');$customer->execute([$orderId]);$o=$customer->fetch();createNotification($db,(int)$o['user_id'],'order','ร้านค้าอัปเดตการจัดส่ง','ออเดอร์ '.$o['order_no'].' เปลี่ยนเป็น '.$status,BASE_URL.'order-detail.php?id='.$orderId);$message='อัปเดตการจัดส่งแล้ว';}catch(Throwable $e){$error=$e->getMessage();}}
$stmt=$db->prepare("SELECT o.id,o.order_no,o.shipping_name,o.shipping_phone,o.shipping_address,o.created_at,COALESCE(f.status,'pending') fulfillment_status,f.carrier,f.tracking_number,SUM(oi.subtotal) seller_total,GROUP_CONCAT(CONCAT(oi.product_name,' × ',oi.quantity) SEPARATOR ' | ') items FROM orders o JOIN order_items oi ON oi.order_id=o.id JOIN products p ON p.id=oi.product_id LEFT JOIN order_fulfillments f ON f.order_id=o.id AND f.seller_id=? WHERE p.seller_id=? AND o.order_status<>'cancelled' GROUP BY o.id,f.id ORDER BY o.id DESC");$stmt->execute([$sellerId,$sellerId]);$orders=$stmt->fetchAll();require_once __DIR__.'/includes/header.php';?>
<link rel="stylesheet" href="<?php echo BASE_URL;?>assets/css/seller.css"><div class="container" style="margin:36px auto 70px"><header class="seller-hero" style="padding:28px"><div><p class="eyebrow">FULFILLMENT</p><h1>ออเดอร์ร้านค้าของฉัน</h1><p>รับออเดอร์ แพ็กสินค้า และแจ้งเลขติดตามให้ลูกค้า</p></div></header><?php if($message):?><p class="seller-success"><?php echo e($message);?></p><?php endif;?><?php if($error):?><p class="seller-error"><?php echo e($error);?></p><?php endif;?><div style="display:grid;gap:16px;margin-top:22px"><?php if(!$orders):?><section class="admin-panel">ยังไม่มีออเดอร์</section><?php endif;?><?php foreach($orders as $o):?><article class="admin-panel"><h3><?php echo e($o['order_no']);?> · <?php echo formatCurrency($o['seller_total']);?></h3><p><?php echo e($o['items']);?></p><small><?php echo e($o['shipping_name'].' · '.$o['shipping_phone']);?><br><?php echo e($o['shipping_address']);?></small><form method="post" class="admin-form-grid" style="margin-top:16px"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="order_id" value="<?php echo (int)$o['id'];?>"><select name="status"><option value="accepted">รับออเดอร์</option><option value="packing">กำลังแพ็ก</option><option value="shipped">จัดส่งแล้ว</option><option value="delivered">ส่งสำเร็จ</option></select><input name="carrier" value="<?php echo e($o['carrier']);?>" placeholder="บริษัทขนส่ง"><input name="tracking_number" value="<?php echo e($o['tracking_number']);?>" placeholder="เลขติดตามพัสดุ"><button class="btn btn-primary">บันทึกสถานะ</button></form></article><?php endforeach;?></div></div><?php require_once __DIR__.'/includes/footer.php';?>
